// Title: How to configure Aspose.Cells FontSettings with a Unicode font (Arial Unicode MS) to render emoji and supplementary characters in PDF output (C#)
// Common Searches: Aspose.Cells C# set default font to Arial Unicode MS for PDF export | Render emoji characters in PDF generated by Aspose.Cells workbook | Save workbook as PDF with Unicode font support using Aspose.Cells .NET | Configure FontSettings to display supplementary Unicode characters in PDF | Ensure Unicode characters appear correctly in PDF from Aspose.Cells | Aspose.Cells PDF export Unicode font configuration example
// Tags: default font Arial Unicode MS Aspose.Cells | unicode font support PDF export .NET | supplementary character rendering Aspose.Cells PDF | emoji rendering PDF Aspose.Cells C# | fontsettings configuration Unicode characters

using System;
using System.IO;
using Aspose.Cells;

// The example creates a new Workbook, sets the default style font to Arial Unicode MS to support supplementary Unicode characters such as emojis, writes an emoji string to cell A1, ensures the output directory exists, and saves the workbook as a PDF while handling potential exceptions.
class Program
{
    static void Main()
    {
        try
        {
            // Create a new workbook
            Workbook workbook = new Workbook();

            // Set a Unicode font that supports supplementary characters (e.g., Arial Unicode MS)
            workbook.DefaultStyle.Font.Name = "Arial Unicode MS";

            // Access the first worksheet
            Worksheet sheet = workbook.Worksheets[0];

            // Example data containing supplementary characters (e.g., emoji)
            sheet.Cells["A1"].PutValue("😀 Unicode test");

            // Define output file path
            string outputPath = "output.pdf";

            // Ensure the directory for the output file exists (if a directory is specified)
            string outputDir = Path.GetDirectoryName(Path.GetFullPath(outputPath));
            if (!string.IsNullOrEmpty(outputDir) && !Directory.Exists(outputDir))
            {
                Directory.CreateDirectory(outputDir);
            }

            // Save the workbook as PDF
            workbook.Save(outputPath, SaveFormat.Pdf);
            Console.WriteLine($"Workbook successfully saved to '{outputPath}'.");
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred: " + ex.Message);
        }
    }
}
